import Foundation

// =============================================================================
// DemoSeed — turns the bundled DemoData.json into the demo's starting tables.
//
// DemoData.json is generated by scripts/build_demo_data.py (never edit it by
// hand). Its rows use the SAME column names as the Supabase tables, except
// that dates are relative ("weeks_ago": 2). `resolve` swaps those helper keys
// for real dates using DemoDateRules (spec 8.2), so afterwards every row looks
// exactly like a row the real database would return.
//
// Rows are kept as JSON-style dictionaries (`DemoRow`) on purpose: the demo
// backend stores them the way a database would and decodes them with the
// same forgiving `Decodable` models the real backend uses.
// =============================================================================

/// One table row: column name → JSON value (String, number, Bool, NSNull,
/// or a nested dictionary like `scraped_mics.payload`).
typealias DemoRow = [String: Any]

/// The demo "database": one array of rows per table.
struct DemoTables {
    var mics: [DemoRow] = []
    var sets: [DemoRow] = []
    var plans: [DemoRow] = []
    var scrapedMics: [DemoRow] = []
    var scrapeLog: [DemoRow] = []
}

enum DemoSeedError: LocalizedError, Equatable {
    case missingFile
    case unreadable(String)

    var errorDescription: String? {
        switch self {
        case .missingFile:
            return "The demo data file (DemoData.json) isn't in the app bundle."
        case .unreadable(let detail):
            return "Couldn't read the demo data (\(detail))."
        }
    }
}

enum DemoSeed {

    /// The bundled file's contents.
    static func bundledJSON(in bundle: Bundle = .main) throws -> Data {
        guard let url = bundle.url(forResource: "DemoData", withExtension: "json") else {
            throw DemoSeedError.missingFile
        }
        do {
            return try Data(contentsOf: url)
        } catch {
            throw DemoSeedError.unreadable(error.localizedDescription)
        }
    }

    /// Parses DemoData.json and resolves every relative date against `today`
    /// (spec 8.2). `calendar` supplies the local time zone for scrape times.
    static func resolve(
        json: Data,
        today: CalendarDate,
        calendar: Calendar = CalendarDate.localCalendar
    ) throws -> DemoTables {
        let object: Any
        do {
            object = try JSONSerialization.jsonObject(with: json)
        } catch {
            throw DemoSeedError.unreadable(error.localizedDescription)
        }
        guard let root = object as? [String: Any] else {
            throw DemoSeedError.unreadable("expected a JSON object at the top level")
        }
        func rows(_ key: String) -> [DemoRow] {
            (root[key] as? [Any] ?? []).compactMap { $0 as? DemoRow }
        }

        var tables = DemoTables()
        tables.mics = rows("mics")
        tables.scrapedMics = rows("scraped_mics")

        // Each mic's weekday, so sets/plans land on the right day of the week.
        var weekdayByMicID: [Int: Weekday] = [:]
        for mic in tables.mics {
            if let id = DemoValue.int(mic["id"]), let weekday = Weekday(name: DemoValue.string(mic["day_of_week"])) {
                weekdayByMicID[id] = weekday
            }
        }
        func weekday(of row: DemoRow) -> Weekday {
            // A row whose mic is unknown just uses today's weekday.
            DemoValue.int(row["open_mic_id"]).flatMap { weekdayByMicID[$0] } ?? today.weekday
        }

        tables.sets = rows("sets").map { row in
            var resolved = row
            let date = DemoDateRules.pastDate(
                on: weekday(of: row), weeksAgo: DemoValue.int(row["weeks_ago"]) ?? 0, today: today
            )
            resolved["date_performed"] = date.isoString
            return stripHelperKeys(resolved)
        }

        tables.plans = rows("plans").map { row in
            var resolved = row
            let date: CalendarDate
            if DemoValue.string(row["when"])?.lowercased() == "upcoming" {
                date = DemoDateRules.upcomingDate(
                    on: weekday(of: row), weeksAhead: DemoValue.int(row["weeks_ahead"]) ?? 0, today: today
                )
            } else {
                date = DemoDateRules.pastDate(
                    on: weekday(of: row), weeksAgo: DemoValue.int(row["weeks_ago"]) ?? 0, today: today
                )
            }
            resolved["plan_date"] = date.isoString
            return stripHelperKeys(resolved)
        }

        tables.scrapeLog = rows("scrape_log").map { row in
            var resolved = row
            let time = DemoDateRules.scrapeTime(
                daysAgo: DemoValue.int(row["days_ago"]) ?? 0,
                hour: DemoValue.int(row["hour"]) ?? 0,
                minute: DemoValue.int(row["minute"]) ?? 0,
                today: today,
                calendar: calendar
            )
            // Written with an explicit "Z" so TimestampParser (which reads
            // zone-less timestamps as UTC) gets the exact instant back.
            resolved["last_scraped"] = utcTimestamp(time)
            return stripHelperKeys(resolved)
        }

        return tables
    }

    /// "2026-10-20T18:07:00Z"
    static func utcTimestamp(_ date: Date) -> String {
        let formatter = ISO8601DateFormatter()
        formatter.formatOptions = [.withInternetDateTime]
        formatter.timeZone = TimeZone(identifier: "UTC")
        return formatter.string(from: date)
    }

    private static func stripHelperKeys(_ row: DemoRow) -> DemoRow {
        var cleaned = row
        for key in DemoDateRules.helperKeys {
            cleaned.removeValue(forKey: key)
        }
        return cleaned
    }
}

// =============================================================================
// DemoValue — reads plain values out of a `DemoRow` (JSON numbers can arrive
// as Int, Double or NSNumber depending on the platform).
// =============================================================================
enum DemoValue {

    static func int(_ value: Any?) -> Int? {
        switch value {
        case let number as Int:
            return number
        case let number as Double:
            return LenientNumber.int(from: number)
        case let number as NSNumber:
            return LenientNumber.int(from: number.doubleValue)
        case let text as String:
            return LenientNumber.int(from: text)
        default:
            return nil
        }
    }

    /// Trimmed, non-blank text (nil for null / missing / blank).
    static func string(_ value: Any?) -> String? {
        TextRules.trimmedOrNil(value as? String)
    }

    /// True for JSON null or a missing key.
    static func isNull(_ value: Any?) -> Bool {
        value == nil || value is NSNull
    }
}
